WITH cleaned AS (SELECT *, CONCAT_WS('-', channel, promo_code) AS channel_promo_code_key FROM promotions WHERE channel IS NOT NULL AND ends_on >= '2024-07-25'), with_window AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM cleaned a LEFT JOIN promotions pr ON a.channel <=> pr.channel AND a.starts_on BETWEEN pr.starts_on AND pr.ends_on), metrics AS (SELECT *, MAX(promo_id) OVER w_grp AS running_max_promo_id, COUNT(promo_id) OVER w_grp AS running_count_promo_id, SUM(promo_id) OVER w_grp AS running_sum_promo_id FROM with_window WINDOW w_grp AS (PARTITION BY promotion_promo_code ORDER BY discount_pct, id, promo_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), base AS (SELECT id, promo_code, starts_on, ends_on, discount_pct, channel_promo_code_key, promo_id, promotion_promo_code, running_max_promo_id, running_count_promo_id, running_max_promo_id * running_count_promo_id AS running_max_promo_id_times_running_count_promo_id FROM metrics WHERE ends_on > DATE '2023-07-10' AND channel IS DISTINCT FROM 'web'), remaining_keys AS (SELECT promo_code FROM base INTERSECT SELECT promo_code FROM promotions WHERE promo_code IN ('VIP', 'WELCOME5')), kept_rows AS (SELECT s.* FROM base s JOIN remaining_keys k ON s.promo_code = k.promo_code), summary AS (SELECT CASE WHEN running_count_promo_id >= 18 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_count_promo_id_tier, DATE_TRUNC('QUARTER', ends_on) AS quarter_start, running_count_promo_id, SIZE(COLLECT_SET(promotion_promo_code)) AS num_promotion_promo_codes, SUM(running_max_promo_id) FILTER (WHERE promo_code = 'BUNDLE') AS bundle_total_running_max_promo_id, COUNT(*) AS cnt, COUNT_IF(promo_code = 'SPRING10') AS spring10_events, COUNT_IF(promotion_promo_code = 'SPRING10') AS spring10_events_2 FROM kept_rows GROUP BY GROUPING SETS ((CASE WHEN running_count_promo_id >= 18 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('QUARTER', ends_on), running_count_promo_id), (CASE WHEN running_count_promo_id >= 18 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('QUARTER', ends_on)), (CASE WHEN running_count_promo_id >= 18 THEN 'PREMIUM' ELSE 'STANDARD' END), ())) SELECT running_count_promo_id, num_promotion_promo_codes, bundle_total_running_max_promo_id, spring10_events, spring10_events_2 FROM summary ORDER BY running_count_promo_id DESC;
